/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: row, outcome, accepted, tracklist
 *   Constants: rowKeys
 * Tests
 *   - expected tracklist rows are normalized, ordered by Disc then Track Number and unchanged when parsed again
 *   - expected tracklist rows outside their bounds are refused with the reason
 *   - expected tracklist rows at one position are refused
 *   - expected tracklist rows are bounded at 32 KB of serialized rows
 *   - a stored expected tracklist is read only when it is well formed
 *   - listener reads exclude the stored field by its name
 *   - expected rows show members at their Disc and Track Number, a missing Disc Number counting as disc 1
 *   - members at one position all fill that row, and members at no position or no row are outside the expected tracklist
 *   - expected rows ignore member lifecycle state and visibility
 *   - rows without members are missing-file rows, and an Album without members makes every row missing
 *   - a pairing is placed only when each paired member sits at an existing row after the selected numbers
 * @end-catalog */

/**
 * Album expected tracklists: row validation and its bounds, the lenient stored reader, the storage builder, rows derived from
 * member positions and the placement check over a pairing. All titles and IDs are synthetic.
 */
import assert from 'node:assert/strict';
import test from 'node:test';

import { boundedJson } from '../../src/administration/import/adminImportValueState';
import {
    EXPECTED_TRACKLIST_LIMITS,
    expectedTrackPosition,
    expectedTrackRows,
    expectedTracklistForStorage,
    expectedTracklistPlaced,
    hasStoredExpectedTracklist,
    parseExpectedTracklistRows,
    storedExpectedTracklist,
    withoutExpectedTracklistProjection,
    withoutExpectedTracklistStage,
    type ExpectedTracklistRow
} from '../../src/services/catalog/albumExpectedTracklist';

const row = (discNumber: number, trackNumber: number, title = `Synthetic ${discNumber}-${trackNumber}`, durationMs: number | null = 200_000) =>
    ({ discNumber, trackNumber, title, durationMs });
/** The refusal reason, or 'accepted'. */
const outcome = (value: unknown) => {
    const parsed = parseExpectedTracklistRows(value);
    return parsed.ok ? 'accepted' : parsed.reason;
};
const accepted = (value: unknown): ExpectedTracklistRow[] => {
    const parsed = parseExpectedTracklistRows(value);
    assert.ok(parsed.ok, JSON.stringify(parsed));
    return parsed.rows;
};
const rowKeys = ['discNumber', 'trackNumber', 'title', 'durationMs'];
const tracklist = () => [row(1, 1, 'Synthetic Opener'), row(1, 2, 'Synthetic Second'), row(2, 1, 'Synthetic Disc Two Opener')];

test('expected tracklist rows are normalized, ordered by Disc then Track Number and unchanged when parsed again', () => {
    const rows = accepted([
        { title: '  Synthetic Disc Two ', durationMs: null, trackNumber: 1, discNumber: 2 },
        row(1, 10, '\tSynthetic Tenth\n'),
        { durationMs: 1, title: 'Cafe\u0301 Synthetic', discNumber: 1, trackNumber: 2 },
        Object.assign(Object.create(null), row(1, 1, 'Synthetic Null Prototype'))
    ]);
    assert.deepEqual(rows, [
        row(1, 1, 'Synthetic Null Prototype'),
        { discNumber: 1, trackNumber: 2, title: 'Caf\u00e9 Synthetic', durationMs: 1 },
        row(1, 10, 'Synthetic Tenth'),
        { discNumber: 2, trackNumber: 1, title: 'Synthetic Disc Two', durationMs: null }
    ]);
    for (const value of rows) {
        assert.deepEqual(Object.keys(value), rowKeys);
        assert.equal(Object.getPrototypeOf(value), Object.prototype);
    }
    const again = accepted(rows);
    assert.deepEqual(again, rows);
    assert.equal(JSON.stringify(again), JSON.stringify(rows));
});

test('expected tracklist rows outside their bounds are refused with the reason', () => {
    for (const value of [[], undefined, null, 'rows', 3, { 0: row(1, 1) }]) assert.equal(outcome(value), 'format', JSON.stringify(value));
    assert.equal(outcome(Array.from({ length: 101 }, (_, index) => row(1, index + 1, 'T'))), 'tooManyRows');
    assert.equal(outcome(Array.from({ length: 100 }, (_, index) => row(1, index + 1))), 'accepted');

    for (const discNumber of [0, 1000, 1.5, -1, '1', null]) assert.equal(outcome([{ ...row(1, 1), discNumber }]), 'format', `disc ${discNumber}`);
    for (const trackNumber of [0, 10_000, 2.5, '3', null]) assert.equal(outcome([{ ...row(1, 1), trackNumber }]), 'format', `track ${trackNumber}`);
    assert.equal(outcome([row(999, 9_999)]), 'accepted');

    const { durationMs: _omitted, ...missingKey } = row(1, 1);
    class SyntheticRow { discNumber = 1; trackNumber = 1; title = 'Synthetic'; durationMs = null; }
    for (const value of [missingKey, { ...row(1, 1), recordingId: 'synthetic' }, new SyntheticRow(), [1, 1, 'Synthetic', null], null, 'row']) {
        assert.equal(outcome([value]), 'format', JSON.stringify(value));
    }

    for (const title of [7, null, '', '   ', '\u3000']) assert.equal(outcome([{ ...row(1, 1), title }]), 'format', JSON.stringify(title));
    assert.equal(accepted([row(1, 1, 'x'.repeat(300))])[0].title.length, 300);
    assert.equal(accepted([row(1, 1, `  ${'x'.repeat(300)} `)])[0].title, 'x'.repeat(300));
    assert.equal(outcome([row(1, 1, 'x'.repeat(301))]), 'length');
    // Titles count UTF-16 units: 150 astral characters fill exactly 300.
    assert.equal(outcome([row(1, 1, '\u{1F3B5}'.repeat(150))]), 'accepted');
    assert.equal(outcome([row(1, 1, '\u{1F3B5}'.repeat(151))]), 'length');

    for (const title of ['Bell\u0007 Synthetic', 'Zero\u200bWidth', 'Joined\u200dSynthetic', 'Lone \ud800 High', 'Lone \udc00 Low', `${'x'.repeat(400)}\u0007`]) {
        assert.equal(outcome([row(1, 1, title)]), 'characters', JSON.stringify(title));
    }

    for (const durationMs of [0, -1, 1.5, 2 ** 53, '1000', Number.NaN, Number.POSITIVE_INFINITY]) {
        assert.equal(outcome([{ ...row(1, 1), durationMs }]), 'format', `duration ${durationMs}`);
    }
    assert.equal(accepted([row(1, 1, 'Synthetic', null)])[0].durationMs, null);
    assert.equal(accepted([row(1, 1, 'Synthetic', 1)])[0].durationMs, 1);
    // A duration has no upper bound of its own, so one implausible length never refuses the release's tracklist.
    assert.equal(accepted([row(1, 1, 'Synthetic', 86_400_001)])[0].durationMs, 86_400_001);
    assert.equal(accepted([row(1, 1, 'Synthetic', Number.MAX_SAFE_INTEGER)])[0].durationMs, Number.MAX_SAFE_INTEGER);

    // The first failing row decides, in input order.
    assert.equal(outcome([row(1, 1, 'Bell\u0007'), row(0, 1)]), 'characters');
    assert.equal(outcome([row(0, 1), row(1, 1, 'Bell\u0007')]), 'format');
});

test('expected tracklist rows at one position are refused', () => {
    assert.equal(outcome([row(1, 1, 'Synthetic First'), row(2, 1, 'Synthetic Other Disc'), row(1, 1, 'Synthetic Again')]), 'duplicatePosition');
    // The same Track Number on another disc is another position.
    assert.equal(accepted([row(1, 1), row(2, 1)]).length, 2);
    // A malformed row after the duplicate is never reached.
    assert.equal(outcome([row(1, 1), row(1, 1), row(0, 0)]), 'duplicatePosition');
});

test('expected tracklist rows are bounded at 32 KB of serialized rows', () => {
    /** 100 ASCII rows whose normalized, sorted JSON is exactly `bytes` long. */
    const sized = (bytes: number) => {
        const rows = Array.from({ length: 100 }, (_, index) => row(1, index + 1, 'a'.repeat(260), null));
        let missing = bytes - Buffer.byteLength(JSON.stringify(rows), 'utf8');
        for (const value of rows) {
            const added = Math.min(missing, 300 - value.title.length);
            value.title += 'a'.repeat(added);
            missing -= added;
        }
        assert.equal(Buffer.byteLength(JSON.stringify(rows), 'utf8'), bytes);
        return rows;
    };
    assert.equal(outcome(sized(32_768)), 'accepted');
    // The largest rows array is also a valid review draft value: two container levels within the bound.
    assert.equal(boundedJson(accepted(sized(32_768)), 2, EXPECTED_TRACKLIST_LIMITS.bytes), true);
    assert.equal(outcome(sized(32_769)), 'size');
    // The bound applies to the normalized rows, so spaces the parser trims never count.
    const padded = sized(32_768);
    padded[0].title = `  ${padded[0].title} `;
    assert.ok(Buffer.byteLength(JSON.stringify(padded), 'utf8') > 32_768);
    assert.equal(outcome(padded), 'accepted');
    // Three UTF-8 bytes per CJK character: 100 rows of 300 exceed the bound.
    assert.equal(outcome(Array.from({ length: 100 }, (_, index) => row(1, index + 1, '\u97f3'.repeat(300)))), 'size');
});

test('a stored expected tracklist is read only when it is well formed', () => {
    const appliedAt = new Date('2026-10-20T08:00:00.000Z');
    const stored = { source: 'musicbrainz', appliedAt, rows: [row(1, 1, 'Synthetic Opener', 215_000), row(1, 2, 'Synthetic Missing', null)] };
    for (const doc of [{}, { expectedTracklist: undefined }, { expectedTracklist: null }]) {
        assert.equal(hasStoredExpectedTracklist(doc), false);
        assert.equal(storedExpectedTracklist(doc), null);
    }
    assert.equal(storedExpectedTracklist(null), null);
    assert.equal(storedExpectedTracklist(undefined), null);
    assert.equal(hasStoredExpectedTracklist({ expectedTracklist: stored }), true);
    assert.deepEqual(storedExpectedTracklist({ expectedTracklist: stored }), stored);
    assert.equal(storedExpectedTracklist({ expectedTracklist: { ...stored, source: 'itunes' } })?.source, 'itunes');

    const malformed: unknown[] = [
        'rows', 0, [stored], { ...stored, source: 'discogs' }, { ...stored, source: undefined },
        { ...stored, appliedAt: new Date(Number.NaN) }, { ...stored, appliedAt: appliedAt.toISOString() },
        { ...stored, rows: [] }, { ...stored, rows: undefined }, { ...stored, rows: [row(1, 1), row(1, 1)] }, { ...stored, rows: [row(1, 1, 'Bell\u0007')] }
    ];
    for (const value of malformed) {
        // A malformed value still counts as stored, so it enters the Album revision.
        assert.equal(hasStoredExpectedTracklist({ expectedTracklist: value }), true, JSON.stringify(value));
        assert.equal(storedExpectedTracklist({ expectedTracklist: value }), null, JSON.stringify(value));
    }
    // An unknown top-level key is ignored, so a later format can add one; rows read as parser output.
    assert.deepEqual(storedExpectedTracklist({ expectedTracklist: { ...stored, futureField: { synthetic: true } } }), stored);
    assert.deepEqual(storedExpectedTracklist({ expectedTracklist: { ...stored, rows: [...stored.rows].reverse() } })?.rows, stored.rows);

    const built = expectedTracklistForStorage('itunes', appliedAt, [row(1, 2, ' Synthetic Second '), row(1, 1, 'Synthetic First', null)]);
    assert.ok(built.ok);
    assert.deepEqual(Object.keys(built.tracklist), ['source', 'appliedAt', 'rows']);
    assert.deepEqual(built.tracklist, { source: 'itunes', appliedAt, rows: [row(1, 1, 'Synthetic First', null), row(1, 2, 'Synthetic Second')] });
    for (const [source, date] of [['discogs', appliedAt], [undefined, appliedAt], ['musicbrainz', new Date(Number.NaN)], ['musicbrainz', '2026-10-20']]) {
        assert.deepEqual(expectedTracklistForStorage(source, date, stored.rows), { ok: false, reason: 'format' }, `${source} ${date}`);
    }
    assert.deepEqual(expectedTracklistForStorage('musicbrainz', appliedAt, [row(1, 1), row(1, 1)]), { ok: false, reason: 'duplicatePosition' });
});

test('listener reads exclude the stored field by its name', () => {
    assert.deepEqual(withoutExpectedTracklistProjection, { expectedTracklist: 0 });
    assert.deepEqual(withoutExpectedTracklistStage, { $unset: 'expectedTracklist' });
});

test('expected rows show members at their Disc and Track Number, a missing Disc Number counting as disc 1', () => {
    const rows = tracklist();
    const derived = expectedTrackRows(rows, [
        { id: 'disc-two', discNumber: 2, trackNumber: 1 },
        { id: 'no-disc', discNumber: undefined, trackNumber: 1 },
        { id: 'invalid-disc', discNumber: 0, trackNumber: 2 }
    ]);
    assert.deepEqual(derived.rows.map(view => [view.title, view.memberIds]), [
        ['Synthetic Opener', ['no-disc']], ['Synthetic Second', ['invalid-disc']], ['Synthetic Disc Two Opener', ['disc-two']]
    ]);
    assert.deepEqual(derived.outsideMemberIds, []);
    for (const view of derived.rows) assert.deepEqual(Object.keys(view), [...rowKeys, 'memberIds']);
    // Deriving never changes the stored rows.
    assert.deepEqual(rows, tracklist());

    assert.deepEqual(expectedTrackPosition(undefined, 4), { discNumber: 1, trackNumber: 4 });
    assert.deepEqual(expectedTrackPosition(null, 4), { discNumber: 1, trackNumber: 4 });
    assert.deepEqual(expectedTrackPosition('2', 4), { discNumber: 1, trackNumber: 4 });
    assert.deepEqual(expectedTrackPosition(3, 9_999), { discNumber: 3, trackNumber: 9_999 });
    for (const trackNumber of [undefined, null, 0, 10_000, 1.5, '3']) assert.equal(expectedTrackPosition(1, trackNumber), null, `track ${trackNumber}`);
});

test('members at one position all fill that row, and members at no position or no row are outside the expected tracklist', () => {
    const derived = expectedTrackRows(tracklist(), [
        { id: 'untagged', discNumber: 1, trackNumber: null },
        { id: 'first-copy', discNumber: 1, trackNumber: 1 },
        { id: 'beyond', discNumber: 1, trackNumber: 3 },
        { id: 'second-copy', discNumber: undefined, trackNumber: 1 },
        { id: 'third-disc', discNumber: 3, trackNumber: 1 },
        { id: 'invalid-track', discNumber: 1, trackNumber: 0 }
    ]);
    assert.deepEqual(derived.rows.map(view => view.memberIds), [['first-copy', 'second-copy'], [], []]);
    assert.deepEqual(derived.outsideMemberIds, ['untagged', 'beyond', 'third-disc', 'invalid-track']);
});

test('expected rows ignore member lifecycle state and visibility', () => {
    const members = [
        { id: 'hidden', discNumber: 1, trackNumber: 1, visibility: 'hidden', state: 'ready' },
        { id: 'failed', discNumber: 1, trackNumber: 2, visibility: 'public', state: 'failed' },
        { id: 'unpublished', discNumber: 2, trackNumber: 1, visibility: 'hidden', state: 'unpublished' }
    ];
    const derived = expectedTrackRows(tracklist(), members);
    assert.deepEqual(derived.rows.map(view => view.memberIds), [['hidden'], ['failed'], ['unpublished']]);
    assert.deepEqual(derived.outsideMemberIds, []);
    assert.deepEqual(expectedTrackRows(tracklist(), members.map(({ id, discNumber, trackNumber }) => ({ id, discNumber, trackNumber }))), derived);
});

test('rows without members are missing-file rows, and an Album without members makes every row missing', () => {
    const partial = expectedTrackRows(tracklist(), [{ id: 'opener', discNumber: 1, trackNumber: 1 }]);
    assert.deepEqual(partial.rows.filter(view => view.memberIds.length === 0).map(view => view.title), ['Synthetic Second', 'Synthetic Disc Two Opener']);
    assert.deepEqual(expectedTrackRows(tracklist(), []), { rows: tracklist().map(value => ({ ...value, memberIds: [] })), outsideMemberIds: [] });
});

test('a pairing is placed only when each paired member sits at an existing row after the selected numbers', () => {
    const rows = tracklist();
    const pairs = [{ slotId: 'a', discNumber: 1, trackNumber: 1 }, { slotId: 'b', discNumber: 2, trackNumber: 1 }];
    const numbers = (entries: [string, unknown, unknown][]) =>
        new Map(entries.map(([slotId, discNumber, trackNumber]) => [slotId, { discNumber, trackNumber }]));

    assert.deepEqual(expectedTracklistPlaced(rows, pairs, numbers([['a', 1, 1], ['b', 2, 1]])), { placed: true });
    assert.deepEqual(expectedTracklistPlaced(rows, [pairs[0]], numbers([['a', undefined, 1]])), { placed: true }, 'a missing disc is disc 1');
    assert.deepEqual(expectedTracklistPlaced(rows, pairs, numbers([['a', 1, 2], ['b', 2, 1]])), { placed: false, offSlotIds: ['a'] }, 'renumbered');
    assert.deepEqual(expectedTracklistPlaced(rows, pairs, numbers([['a', 1, 1], ['b', null, 1]])), { placed: false, offSlotIds: ['b'] }, 'missing disc against disc 2');
    const keptUnrelated = [row(1, 1, 'Synthetic Kept Opener'), row(1, 2, 'Synthetic Kept Second')];
    assert.deepEqual(expectedTracklistPlaced(keptUnrelated, pairs, numbers([['a', 1, 1], ['b', 2, 1]])), { placed: false, offSlotIds: ['b'] }, 'no row there');
    assert.deepEqual(expectedTracklistPlaced(rows, pairs, numbers([['a', 1, 1]])), { placed: false, offSlotIds: ['b'] }, 'slot without numbers');
    assert.deepEqual(expectedTracklistPlaced(rows, pairs, numbers([['a', 1, null], ['b', 2, 1]])), { placed: false, offSlotIds: ['a'] }, 'no Track Number');
    assert.deepEqual(expectedTracklistPlaced(rows, [], new Map()), { placed: true });
    assert.deepEqual(expectedTracklistPlaced([], [], new Map()), { placed: true });

    const repeated = [{ slotId: 'c', discNumber: 1, trackNumber: 2 }, pairs[1], { slotId: 'c', discNumber: 1, trackNumber: 1 }, pairs[0]];
    assert.deepEqual(expectedTracklistPlaced(rows, repeated, numbers([['a', 1, 1], ['b', 1, 1], ['c', 3, 3]])), { placed: false, offSlotIds: ['c', 'b'] });
});
